    "tx": "Tiểu bang đầu tiên phê chuẩn Hiến pháp Hoa Kỳ (1787), nằm trên bán đảo Delmarva án ngữ cửa vịnh Delaware; nhờ hệ thống tòa án thương mại (Court of Chancery) và luật doanh nghiệp ưu việt, hơn 65% các tập đoàn trong danh sách Fortune 500 của Mỹ đăng ký pháp nhân tại bang nhỏ bé này."
